tool_input.command:
$root="D:\repository\skills";
Write-Host "=== skills repo top-level (relevant) ==="; Get-ChildItem $root -Directory | Where-Object { $_.Name -match "openviking|memory" } | ForEach-Object { Write-Host ("  "+$_.Name) };
Write-Host "=== openviking-data top-level ==="; Get-ChildItem "$root\openviking-data" -Force | ForEach-Object { $sz=if($_.PSIsContainer){'(dir)'}else{("{0}MB"-f [math]::Round($_.Length/1MB,1))}; Write-Host ("  "+$_.Name+"  "+$sz) };
Write-Host "=== openviking-data README? ==="; if(Test-Path "$root\openviking-data\README.md"){ Get-Content "$root\openviking-data\README.md" -Encoding UTF8 -First 30 } else { "  (none)" };
Write-Host "=== openviking-memory top-level ==="; Get-ChildItem "$root\openviking-memory" -Force -ErrorAction SilentlyContinue | Select-Object -First 8 | ForEach-Object { Write-Host ("  "+$_.Name) }

$root="D:\repository\skills\openviking-data\viking\default\user\default";
# find one memory md and show its frontmatter head
$m=Get-ChildItem "$root\memories" -Recurse -Filter "*.md" -ErrorAction SilentlyContinue | Select-Object -First 1;
Write-Host ("sample memory: "+$m.FullName);
Get-Content $m.FullName -Encoding UTF8 -First 25 | ForEach-Object { Write-Host ("  | "+$_) };
Write-Host "=== provenance markers across memories/sessions? ===";
foreach($k in @("source:","origin:","imported","来源","provenance","source_type","peer")){
  $c=(Get-ChildItem "$root\memories" -Recurse -Filter "*.md" -ErrorAction SilentlyContinue | Select-Object -First 400 | ForEach-Object { (Get-Content $_.FullName -Encoding UTF8 -First 12 -ErrorAction SilentlyContinue) -join "`n" } | Select-String $k).Count;
  Write-Host ("  '$k' appears in <=400 sampled memories: $c")
}
